"""Worker-executed disk tier I/O.

The stock secondary-tier design does all file I/O in the scheduler process,
against the scheduler's mmap of the shared offload region. That is only
correct when every worker shares that mmap — i.e. when all ranks run on the
scheduler's node. With ranks on other machines (Ray multi-node TP), a
scheduler-side tier persists rows whose remote-rank slices were never
written, and a promotion materializes data into a file the remote rank does
not map: the remote rank then swaps stale bytes into its GPU. Measured on a
2-box TP=2 cluster as 100%% "hits" restoring functionally wrong KV (0/8
needles vs 8/8 fresh).

This module is the data plane for the distributed variant: the scheduler
still makes every decision (what to store, evict, promote — see
``LRUFileSystemTierManager``), but ships the byte movement to each worker as
``DiskJobDirective`` entries in the per-step connector metadata. Every rank
reads/writes ONLY its own slice of its own node-local mmap, under its own
node-local ``<base>_r<rank>`` directory. A job completes when every rank has
reported it, so ordering degenerates to the same guarantee the stock design
had: cascades run after the GPU->CPU swap completed everywhere, GPU loads
start only after the promote completed everywhere.

Failure never blocks: a rank that cannot read a block reports the job failed,
the scheduler deregisters the key, and the lookup degrades to a miss (the
prefix is recomputed).

Torch-free on purpose so the directive types and executor are unit-testable
outside the container.
"""

import os
import threading
from collections import deque
from collections.abc import Callable, Iterable
from dataclasses import dataclass, field
from functools import partial

from vllm.logger import init_logger

logger = init_logger(__name__)

CONFIG_DIGEST_LEN = 10


class _JobState:
    """Thread-safe completion tracker for one job's per-block I/O tasks.

    Same contract as tiering/fs/thread_pool.JobState; carried here (with the
    pool below) so this module has no imports beyond vllm.logger and stays
    unit-testable outside the image.
    """

    __slots__ = ("job_id", "_n_tasks", "_completed", "_success", "_lock")

    def __init__(self, job_id: int, n_tasks: int) -> None:
        self.job_id = job_id
        self._n_tasks = n_tasks
        self._completed = 0
        self._success = True
        self._lock = threading.Lock()

    def task_done(self, success: bool) -> tuple[bool, bool]:
        """Returns (job finished, job success so far)."""
        with self._lock:
            self._completed += 1
            if not success:
                self._success = False
            return self._completed == self._n_tasks, self._success


class _DualQueuePool:
    """Two task queues (load, store) with two thread groups; load-priority
    threads drain loads first and vice versa, so neither direction starves."""

    def __init__(
        self, n_read_threads: int, n_write_threads: int, name_prefix: str
    ) -> None:
        self._load_q: deque = deque()
        self._store_q: deque = deque()
        self._condition = threading.Condition(threading.Lock())
        self._stop = False
        self._threads: list[threading.Thread] = []
        self._finished_q: deque[tuple[int, bool]] = deque()
        for load_priority, count, tag in (
            (True, n_read_threads, "l"),
            (False, n_write_threads, "s"),
        ):
            for i in range(count):
                t = threading.Thread(
                    target=self._worker,
                    args=(load_priority,),
                    name=f"{name_prefix}_{tag}{i}",
                    daemon=True,
                )
                t.start()
                self._threads.append(t)

    def enqueue(
        self,
        is_load: bool,
        job_id: int,
        tasks: list[Callable[[], None]],
    ) -> None:
        state = _JobState(job_id, len(tasks))
        queue = self._load_q if is_load else self._store_q
        with self._condition:
            for fn in tasks:
                queue.append((fn, state))
            self._condition.notify(len(tasks))

    def get_finished(self) -> list[tuple[int, bool]]:
        jobs = []
        while self._finished_q:
            jobs.append(self._finished_q.popleft())
        return jobs

    def shutdown(self, wait: bool = True) -> None:
        with self._condition:
            self._stop = True
            self._load_q.clear()
            self._store_q.clear()
            self._condition.notify_all()
        if wait:
            for t in self._threads:
                t.join()

    def _worker(self, load_priority: bool) -> None:
        while True:
            with self._condition:
                self._condition.wait_for(
                    lambda: self._stop or self._load_q or self._store_q
                )
                if self._stop:
                    return
                primary = self._load_q if load_priority else self._store_q
                secondary = self._store_q if load_priority else self._load_q
                task, state = primary.popleft() if primary else secondary.popleft()
            try:
                task()
                job_finished, success = state.task_done(True)
            except Exception as exc:  # noqa: BLE001
                logger.error("disk job %s block I/O failed: %s", state.job_id, exc)
                job_finished, success = state.task_done(False)
            if job_finished:
                self._finished_q.append((state.job_id, success))


@dataclass(slots=True)
class DiskJobDirective:
    """One scheduler-decided disk job, executed independently by every rank.

    ``blocks`` pairs a block file path (relative to the rank's own base
    directory) with the primary-tier block id whose slice to read or fill.
    """

    job_id: int
    is_load: bool
    blocks: list[tuple[str, int]] = field(default_factory=list)


def rank_base_dir(root_dir: str, model_name: str, rank: int) -> str:
    """This rank's block directory.

    Built ONLY from values every process reads from the same literal source
    (the tier config's root_dir and the CLI model name) plus the process's
    own rank. Deliberately NOT derived from resolved engine config: the
    scheduler and the workers resolve some fields differently (measured:
    cache dtype "fp8" scheduler-side vs the worker-resolved runtime dtype),
    so any digest over resolved config gives the scheduler a seed directory
    no worker ever writes.
    """
    safe_model = model_name.replace("/", "_")
    return os.path.join(root_dir, f"{safe_model}_r{rank}")


def rel_block_path(cfg_prefix: str, block_hash: bytes, group_idx: int) -> str:
    """Relative block-file path shared by all ranks.

    ``cfg_prefix`` is a short digest of the SCHEDULER's run config (dtype,
    block sizes, kv groups, parallel layout). Only the scheduler generates
    relative paths — workers just join them under their base dir — so a
    config change moves the namespace without needing any cross-process
    agreement. Blocks from an older config can still be adopted at seed time
    (they count against the cap and, being oldest, evict first) but can never
    be looked up, so stale geometry is never served.

    Hash-based subdirectories bound directory fan-out.
    """
    hash_hex = block_hash.hex()
    return (
        f"{cfg_prefix}/{hash_hex[:3]}/{hash_hex[3:5]}_g{group_idx}/"
        f"{hash_hex}.bin"
    )


def _store_slice(path: str, buffer: memoryview, offset: int, length: int) -> None:
    """Write one slice to ``path`` atomically (tmp + rename); skip if present.

    Content-addressed filenames make the skip safe: an existing file already
    holds these bytes. No O_DIRECT — a slice is not sector-aligned in general,
    and buffered writes are the point of the file-backed staging design (the
    kernel absorbs them as page cache and writes back at leisure).
    """
    if os.path.exists(path):
        return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp_path = f"{path}.{os.getpid()}_{threading.get_native_id()}.tmp"
    view = buffer.cast("B")[offset : offset + length]
    try:
        fd = os.open(tmp_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
        try:
            written = os.write(fd, view)
            if written != length:
                raise OSError(f"short write: {written} of {length} bytes")
        finally:
            os.close(fd)
        os.replace(tmp_path, path)
    except Exception:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise


def _load_slice(path: str, buffer: memoryview, offset: int, length: int) -> None:
    """Read one slice from ``path`` into the mmap; drop the file if unreadable.

    The local remove on failure is deliberate: the scheduler will also
    deregister the key and broadcast a delete when the failure is reported,
    but removing the bad file immediately keeps this rank from serving it
    again if that delete is lost (e.g. an engine restart in between).
    """
    view = buffer.cast("B")[offset : offset + length]
    fd: int | None = None
    try:
        fd = os.open(path, os.O_RDONLY)
        read = os.readv(fd, [view])
        if read != length:
            raise OSError(f"short read: {read} of {length} bytes")
    except Exception:
        try:
            os.remove(path)
        except OSError:
            pass
        raise
    finally:
        if fd is not None:
            os.close(fd)


class DiskJobExecutor:
    """Per-rank data plane: executes DiskJobDirectives against this rank's
    slice of the node-local offload mmap and its node-local block directory.

    ``poll_finished()`` yields (job_id, success) pairs; the connector worker
    forwards them to the scheduler, which finalizes a job once every rank has
    reported.
    """

    def __init__(
        self,
        base_dir: str,
        kv_buffer: memoryview,
        row_stride: int,
        slice_start: int,
        slice_size: int,
        n_read_threads: int = 8,
        n_write_threads: int = 8,
    ) -> None:
        assert slice_start + slice_size <= row_stride, (
            f"rank slice [{slice_start}, {slice_start + slice_size}) exceeds "
            f"row stride {row_stride}"
        )
        self._base_dir = base_dir
        self._kv_buffer = kv_buffer
        self._row_stride = row_stride
        self._slice_start = slice_start
        self._slice_size = slice_size
        os.makedirs(base_dir, exist_ok=True)
        self._pool = _DualQueuePool(
            n_read_threads,
            n_write_threads,
            name_prefix="vllm_kv_disk",
        )
        # Directives with no blocks complete here: JobState only fires after
        # n_tasks task_done() calls, so an empty job would never finish.
        self._instantly_finished: list[tuple[int, bool]] = []
        logger.info(
            "disk tier executor: base_dir=%s slice=[%d, %d) of %d-byte rows",
            base_dir,
            slice_start,
            slice_start + slice_size,
            row_stride,
        )

    def _abs(self, rel_path: str) -> str:
        return os.path.join(self._base_dir, rel_path)

    def _offset(self, block_id: int) -> int:
        return block_id * self._row_stride + self._slice_start

    def submit(
        self,
        directives: Iterable[DiskJobDirective],
        files_to_remove: Iterable[str] = (),
    ) -> None:
        for rel_path in files_to_remove:
            try:
                os.remove(self._abs(rel_path))
            except FileNotFoundError:
                pass
            except OSError as exc:
                logger.warning(
                    "disk tier: could not remove %s: %s", rel_path, exc
                )

        for directive in directives:
            io_fn = _load_slice if directive.is_load else _store_slice
            tasks = [
                partial(
                    io_fn,
                    self._abs(rel_path),
                    self._kv_buffer,
                    self._offset(block_id),
                    self._slice_size,
                )
                for rel_path, block_id in directive.blocks
            ]
            if not tasks:
                self._instantly_finished.append((directive.job_id, True))
                continue
            self._pool.enqueue(directive.is_load, directive.job_id, tasks)

    def poll_finished(self) -> list[tuple[int, bool]]:
        finished = self._pool.get_finished()
        if self._instantly_finished:
            finished.extend(self._instantly_finished)
            self._instantly_finished.clear()
        return finished

    def shutdown(self) -> None:
        self._pool.shutdown(wait=True)
